PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
    id TEXT PRIMARY KEY,
    telegram_id TEXT UNIQUE,
    full_name TEXT,
    username TEXT,
    device_fingerprint TEXT,
    is_approved INTEGER DEFAULT 0,
    is_admin INTEGER DEFAULT 0,
    created_at INTEGER
);
CREATE TABLE sessions (
    token TEXT PRIMARY KEY,
    user_id TEXT,
    created_at INTEGER
);
CREATE TABLE messages (
    id TEXT PRIMARY KEY,
    sender_id TEXT,
    sender_name TEXT,
    text TEXT,
    is_from_telegram INTEGER DEFAULT 0,
    timestamp INTEGER
, reply_to_name TEXT, reply_to_text TEXT, reply_to_id TEXT, tg_msg_id INTEGER, is_read INTEGER DEFAULT 0, read_at INTEGER, is_edited INTEGER DEFAULT 0, is_pinned INTEGER DEFAULT 0, reactions TEXT DEFAULT '{}', media_type TEXT, media_file_id TEXT, media_file_name TEXT, media_file_size INTEGER, media_thumb_id TEXT, media_duration INTEGER DEFAULT 0);
CREATE TABLE push_subscriptions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER,
  endpoint TEXT UNIQUE,
  p256dh TEXT,
  auth TEXT,
  created_at INTEGER,
  updated_at INTEGER
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_messages_timestamp ON messages(timestamp);
